import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

enum GalaxyWorldKind { vegeta, game, identity, cinema, creation, music, family, archive, comingSoon }

class GalaxyWorld {
  final GalaxyWorldKind kind;
  final String title;
  final String description;
  const GalaxyWorld({required this.kind, required this.title, required this.description});
}

class DarkestWorldUniverse extends StatefulWidget {
  final List<GalaxyWorld> worlds;
  final ValueChanged<GalaxyWorld>? onWorldTap;
  const DarkestWorldUniverse({super.key, required this.worlds, this.onWorldTap});
  @override State<DarkestWorldUniverse> createState() => _DarkestWorldUniverseState();
}

class _DarkestWorldUniverseState extends State<DarkestWorldUniverse> with SingleTickerProviderStateMixin {
  late final AnimationController clock = AnimationController(vsync: this, duration: const Duration(seconds: 70))..repeat();
  GalaxyWorldKind? selected;
  GalaxyWorldKind? hovered;
  double orbit = 0;
  double zoom = 1;
  bool systemMap = false;
  bool labels = true;
  bool detail = true;
  bool cinematic = false;
  bool paused = false;

  @override void initState() { super.initState(); clock.addListener(_tick); }
  void _tick() { if (paused && clock.isAnimating) clock.stop(); else if (!paused && !clock.isAnimating) clock.repeat(); }
  @override void dispose() { clock.removeListener(_tick); clock.dispose(); super.dispose(); }
  GalaxyWorld? get current => selected == null ? null : widget.worlds.cast<GalaxyWorld?>().firstWhere((w) => w!.kind == selected, orElse: () => null);
  void select(GalaxyWorld w) => setState(() => selected = selected == w.kind ? null : w.kind);
  void visit() { final w = current; if (w != null) widget.onWorldTap?.call(w); }
  void reset() => setState(() { orbit = 0; zoom = 1; selected = null; hovered = null; systemMap = false; labels = true; detail = true; cinematic = false; paused = false; });

  @override Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context); final compact = size.width < 760; final chosen = current;
    final effectiveCinematic = cinematic && size.width >= 900 && size.height >= 600;
    return FocusableActionDetector(
      autofocus: true,
      shortcuts: const <ShortcutActivator, Intent>{
        SingleActivator(LogicalKeyboardKey.enter): ActivateIntent(), SingleActivator(LogicalKeyboardKey.escape): DismissIntent(),
        SingleActivator(LogicalKeyboardKey.keyP): _PauseIntent(), SingleActivator(LogicalKeyboardKey.keyL): _LabelsIntent(),
        SingleActivator(LogicalKeyboardKey.keyM): _MapIntent(), SingleActivator(LogicalKeyboardKey.keyD): _DetailIntent(),
        SingleActivator(LogicalKeyboardKey.keyC): _CinemaIntent(), SingleActivator(LogicalKeyboardKey.keyR): _ResetIntent(),
      },
      actions: <Type, Action<Intent>>{
        ActivateIntent: CallbackAction<ActivateIntent>(onInvoke: (_) { visit(); return null; }),
        DismissIntent: CallbackAction<DismissIntent>(onInvoke: (_) { setState(() => selected = null); return null; }),
        _PauseIntent: CallbackAction<_PauseIntent>(onInvoke: (_) { setState(() => paused = !paused); return null; }),
        _LabelsIntent: CallbackAction<_LabelsIntent>(onInvoke: (_) { setState(() => labels = !labels); return null; }),
        _MapIntent: CallbackAction<_MapIntent>(onInvoke: (_) { setState(() => systemMap = !systemMap); return null; }),
        _DetailIntent: CallbackAction<_DetailIntent>(onInvoke: (_) { setState(() => detail = !detail); return null; }),
        _CinemaIntent: CallbackAction<_CinemaIntent>(onInvoke: (_) { setState(() => cinematic = !cinematic); return null; }),
        _ResetIntent: CallbackAction<_ResetIntent>(onInvoke: (_) { reset(); return null; }),
      },
      child: Scaffold(
        backgroundColor: const Color(0xFF010107),
        body: GestureDetector(
          onScaleUpdate: (d) => setState(() { if (d.pointerCount > 1) zoom = (zoom * d.scale).clamp(.66, 1.70).toDouble(); else orbit += d.focalPointDelta.dx / math.max(220.0, size.width); }),
          child: AnimatedBuilder(
            animation: clock,
            builder: (_, __) => Stack(fit: StackFit.expand, children: [
              RepaintBoundary(child: CustomPaint(painter: _DeepSpacePainter(clock.value, detail, effectiveCinematic))),
              RepaintBoundary(child: CustomPaint(painter: _GalaxyDustPainter(clock.value, effectiveCinematic))),
              Transform.scale(scale: zoom, child: RepaintBoundary(child: CustomPaint(painter: _OrbitArchitecturePainter(clock.value, orbit, systemMap, detail, effectiveCinematic)))),
              _WorldOrbit(worlds: widget.worlds, phase: clock.value, orbit: orbit, selected: selected, hovered: hovered, labels: labels, detail: detail, cinematic: effectiveCinematic, compact: compact, onTap: select, onHover: (w) => setState(() => hovered = w?.kind)),
              _Header(systemMap: systemMap, compact: compact, cinematic: effectiveCinematic, paused: paused),
              Positioned(right: compact ? 10 : 26, top: compact ? 70 : 26, child: _Controls(map: systemMap, labels: labels, detail: detail, cinematic: effectiveCinematic, paused: paused, onIn: () => setState(() => zoom = (zoom + .1).clamp(.66, 1.70).toDouble()), onOut: () => setState(() => zoom = (zoom - .1).clamp(.66, 1.70).toDouble()), onMap: () => setState(() => systemMap = !systemMap), onLabels: () => setState(() => labels = !labels), onDetail: () => setState(() => detail = !detail), onCinematic: () => setState(() => cinematic = !cinematic), onPause: () => setState(() => paused = !paused), onReset: reset)),
              Positioned(left: compact ? 12 : 30, top: compact ? 112 : 92, child: _Telemetry(phase: clock.value, selected: chosen, hovered: hovered, map: systemMap, zoom: zoom, cinematic: effectiveCinematic, paused: paused)),
              if (chosen != null) _FloatingVisitPanel(world: chosen, compact: compact, phase: clock.value, orbit: orbit, count: widget.worlds.length, index: widget.worlds.indexOf(chosen), onVisit: visit, onClose: () => setState(() => selected = null)) else const Positioned(left: 0, right: 0, bottom: 22, child: Center(child: _Hint())),
            ]),
          ),
        ),
      ),
    );
  }
}

